46	    /** 计划申报 OAR 剂量行。 */
47	    public record OarDoseRow(
48	            Long id,
49	            Long planVersionId,
50	            String organCode,
51	            String metricType,
52	            Long metricRef,
53	            BigDecimal metricValue) {
54	    }
55	
56	    /** 患者在执行计划守卫行。 */
57	    public record ActivePlanRow(
58	            String patientId,
59	            String planCode,
60	            Long planVersionId,
61	            String status,
62	            LocalDateTime updatedAt) {
63	    }
64	
65	    private static final class PlanVersionRowMapper implements RowMapper<PlanVersionRow> {
66	        @Override
67	        public PlanVersionRow mapRow(ResultSet rs, int rowNum) throws SQLException {
68	            return new PlanVersionRow(
69	                    rs.getLong("id"),
70	                    rs.getString("patient_id"),
71	                    rs.getString("plan_code"),
72	                    rs.getInt("version_no"),
73	                    rs.getString("template_code"),
74	                    rs.getLong("prescribed_total_dose_cgy"),
75	                    rs.getLong("fraction_dose_cgy"),
76	                    rs.getInt("fraction_count"),
77	                    rs.getString("status"),
78	                    rs.getTimestamp("created_at").toLocalDateTime(),
79	                    toLdt(rs, "reviewed_at"),
80	                    toLdt(rs, "approved_at"),
81	                    toLdt(rs, "verified_at"),
