92	    private static final class OarDoseRowMapper implements RowMapper<OarDoseRow> {
93	        @Override
94	        public OarDoseRow mapRow(ResultSet rs, int rowNum) throws SQLException {
95	            Long metricRef = (Long) rs.getObject("metric_ref");
96	            return new OarDoseRow(
97	                    rs.getLong("id"),
