153	    public Optional<PlanVersionRow> findVersion(String patientId, String planCode, int versionNo) {
154	        List<PlanVersionRow> rows = jdbc.query("""
155	                SELECT id, patient_id, plan_code, version_no, template_code,
156	                       prescribed_total_dose_cgy, fraction_dose_cgy, fraction_count, status,
