193	
194	    /** 按主键锁定计划版本行（SELECT ... FOR UPDATE）。 */
195	    public Optional<PlanVersionRow> lockVersionById(long planVersionId) {
196	        List<PlanVersionRow> rows = jdbc.query("""
197	                SELECT id, patient_id, plan_code, version_no, template_code,
