313	    /**
314	     * 对患者主记录加行级排他锁（SELECT ... FOR UPDATE），
315	     * 用于串行化同一患者的并发批准/结案，保证唯一在执行计划。
316	     *
317	     * @return 患者是否存在
318	     */
319	    public boolean lockPatient(String patientId) {
320	        List<String> locked = jdbc.query(
321	                "SELECT patient_id FROM patient WHERE patient_id = ? FOR UPDATE",
322	                (rs, n) -> rs.getString(1), patientId);
323	        return !locked.isEmpty();
324	    }
