                PlanStatus.valueOf(row.status()),
                odt(row.createdAt()),
                odt(row.reviewedAt()),
                odt(row.approvedAt()),
                odt(row.verifiedAt()),
                odt(row.firstFractionAt()),
                odt(row.closedAt()),
                odt(row.invalidatedAt()));
    }
}

