public abstract class AbstractIntegrationTest {

    @Autowired
    protected PlanRepository planRepository;

    @Autowired
    protected DirectoryRepository directoryRepository;

    @Autowired
    protected Clock clock;

    /** 清理由 {@link #cleanDatabase()} 在非事务上下文中完成，以真正提交清空。 */
