28	class WorkflowLifecycleTest extends AbstractIntegrationTest {
29	
30	    private static final String PATIENT = "P1";
31	    private static final String PLAN = "PLAN_A";
32	    private static final String TPL = "TPL1";
33	
34	    @Autowired
35	    private WorkflowService workflow;
36	
37	    /** 准备：患者 + 模板 + 一个剂量合法、勾稽一致的 DESIGN 计划 v1（恰等限值）。 */
38	    private long setupValidPlan() {
39	        patient(PATIENT, "测试患者甲");
40	        pelvisTemplate(TPL, 4500L, new BigDecimal("40.00"));
41	        // 200cGy × 25 = 5000cGy；脊髓恰等 4500，膀胱恰等 40.00
42	        return createPlanVersion(PATIENT, PLAN, 1, TPL, 5000L, 200L, 25,
43	                4500L, new BigDecimal("40.00"));
44	    }
45	
46	    private AuditResponse auditOk(String reqId) {
47	        RecordedResponse result = workflow.audit(PATIENT, PLAN, 1, reqId);
48	        assertThat(result.httpStatus()).isEqualTo(200);
49	        return (AuditResponse) result.body();
50	    }
51	
52	    private ApprovalResponse approveOk(int versionNo, String reqId) {
53	        RecordedResponse result = workflow.approve(PATIENT, PLAN, versionNo, reqId);
54	        assertThat(result.httpStatus()).isEqualTo(200);
55	        return (ApprovalResponse) result.body();
56	    }
57	
58	    @Test
59	    @DisplayName("约束恰等限值 + 总剂量勾稽一致：物理审核通过")
60	    void auditPassesAtExactLimit() {
61	        setupValidPlan();
62	        AuditResponse audit = auditOk("AUD-1");
63	
64	        assertThat(audit.status()).isEqualTo(PlanStatus.REVIEWED.name());
65	        assertThat(audit.passed()).isTrue();
66	        assertThat(audit.totalDoseCheckOk()).isTrue();
67	        assertThat(audit.items()).hasSize(2);
68	        assertThat(audit.items()).allSatisfy(item -> assertThat(item.withinLimit()).isTrue());
69	        assertThat(audit.replayed()).isFalse();
70	
71	        PlanVersionRow row = planRepository.findVersion(PATIENT, PLAN, 1).orElseThrow();
72	        assertThat(row.status()).isEqualTo(PlanStatus.REVIEWED.name());
73	        assertThat(row.reviewedAt()).isNotNull();
74	    }
