83	                4501L, new BigDecimal("40.00"));
84	
85	        RecordedResponse result = workflow.audit(PATIENT, PLAN, 1, "AUD-BAD");
86	        assertThat(result.httpStatus()).isEqualTo(422);
87	        RejectionBody body = (RejectionBody) result.body();
88	        assertThat(body.code()).isEqualTo("AUDIT_REJECTED");
89	        assertThat(body.details()).isNotEmpty();
