91	        PlanVersionRow row = planRepository.findVersion(PATIENT, PLAN, 1).orElseThrow();
92	        assertThat(row.status()).isEqualTo(PlanStatus.DESIGN.name());
93	        assertThat(workflow.recomputeAudit(PATIENT, PLAN, 1).auditStored()).isFalse();
94	    }
