96	    @Test
97	    @DisplayName("总剂量勾稽不一致（分次剂量×次数≠处方）：422 拒绝")
98	    void auditRejectsTotalDoseMismatch() {
99	        patient(PATIENT, "测试患者甲");
100	        pelvisTemplate(TPL, 4500L, new BigDecimal("40.00"));
101	        // 201 × 25 = 5025 ≠ 5000
102	        createPlanVersion(PATIENT, PLAN, 1, TPL, 5000L, 201L, 25,
