    private final WorkflowRepository workflowRepository;
    private final IdempotencyTemplate idempotency;
    private final Clock clock;

    // 设备登记
    @Transactional
    public RecordedResponse registerDevice(DeviceRegisterRequest request) {
        Map params = {deviceId, deviceName, maxComplexityLevel}
        return idempotency.executeSuccessOnly(DEVICE_REGISTER, requestId, params, () -> doRegister(request));
    }
