    // 能力调整
    @Transactional
    public RecordedResponse updateCapability(String deviceId, DeviceCapabilityRequest request) {
        DeviceRow device = schedulingRepository.lockDevice(deviceId).orElseThrow(404 DEVICE_NOT_FOUND);
        params = {deviceId, maxComplexityLevel, expectedVersion}
        return idempotency.executeSuccessOnly(DEVICE_CAPABILITY, requestId, params, () -> doUpdateCapability(device, request));
    }
